        start += len(results['artists'])
    return artist_map


def get_items_from_cache(aids):
    map = {}
    naids = []

    for aid in aids:
        fitem = cache.get('item', aid)
        if fitem:
            map[aid] = fitem
        else:
            naids.append(aid)
    return map, naids

