        else:
            self.tracks_added_since = -1

        #print "since", tracks_added_since, self.tracks_added_since, date_to_epoch(now())
        #print "before", tracks_added_before, self.tracks_added_before, date_to_epoch(now())

        self.next_offset = 0
        self.limit = 100

        self.tracks = []
        self.total = 1
        self.cur_index = 0
