    if not sp:
        raise Exception("not authenticated for save")

    if not user:
        raise Exception("no authenticated user")

    if not uri:
        response = sp.user_playlist_create(user, title)
        print("create playlist", json.dumps(response, indent=4))
        if 'uri' in response:
            uri = response['uri']
