 # spotify:user:plamere:playlist:5pjUedV8eoCJUiYzyo79eq
 # or spotify:playlist:5pjUedV8eoCJUiYzyo79eq
    split_uri = uri.split(':')
    if len(split_uri) == 5:
        return split_uri[4]
    elif len(split_uri) == 3:
        return split_uri[2]
    else:
        return None

