        uri = response['uri']

        pid = get_pid_from_playlist_uri(uri)
        if pid:
            batch_size = 100
            uris = [ 'spotify:track:' + id for id in self.buffer]
            for start in range(0, len(uris), batch_size):
                turis = uris[start:start+batch_size]
                sp.playlist_add_items(pid, turis)
        else:
