function secsToRelativeTimeString(secs) {
    if (secs == -1) {
      return "";
    } else {
      return secs.toString();
    }
}

function relativeTimeStringToSecs(val) {
    if (val.length == 0) {
      return -1;
    } else {
      return parseInt(val);
    }
}

function clearComponentErrors() {
    $("#errors").empty(200);
    _.each(nameToRect, function(rect, name) {
        if (rect.hasError) {
            rect.hasError = false;
            rect.attr({ stroke: "#000000"});
        }
    });
}

function altSelectRect(rect, state) {
    if (state) {
        rect.attr({'stroke-dasharray' : ['-']});
        rect.attr({'stroke-width' : 6});
    } else {
        rect.attr({'stroke-dasharray' : null});
        rect.attr({'stroke-width' : 1});
    }
}

