/*
 * relative.time.parser.js
 * JS port of app/server/reltime.py
 *
 * Parses English relative-time strings and returns seconds.
 * Throws on bad input.
 *
 * Examples:
 *   parseRelTime("1 month")              -> 2592000
 *   parseRelTime("2 days 2 hours")       -> 180000
 *   parseRelTime("last week")            -> 604800
 *   parseRelTime("twenty days ago")      -> 1728000
 *   parseRelTime("1 h 3 w 2 d")         -> 1990800
 */

(function(root) {
    var STOP_WORDS = { 'and': true, 'ago': true, 'since': true };

