def _find_playlist_by_name(sp, user, name):
    batch_size = 50
    for start in range(0, 1000, batch_size):
        playlists = sp.current_user_playlists(limit=batch_size, offset=start)
        for playlist in playlists['items']:
            if playlist['name'] == name:
                return playlist['uri']
    return None

