def get_artist_uri(artist_name):
    sp = get_spotify()
    if sp:
        results = sp.search(artist_name, limit=5, type='artist')
        if 'artists' in results and 'items' in results['artists'] and len(results['artists']['items']) > 0:
            return results['artists']['items'][0]['uri']
